1	//! Resolving the feature prompt from a string, a file, or stdin.
2	//!
3	//! `derrick add` / `derrick run add-feature` accept the feature brief three
4	//! ways so that a large multi-line `/speckit.specify`-style prompt (newlines,
5	//! quotes, `$`) can be supplied without shell-escaping pain:
6	//!
7	//! 1. the positional argument / `--prompt "..."` string,
8	//! 2. `--prompt-file <path>` (a file to read),
9	//! 3. stdin (piped, or explicitly via the `-` sentinel).
10	//!
11	//! [`resolve_prompt`] folds those three sources into the single
12	//! `Option<String>` that feeds `state.prompt`.  Exactly one explicit source is
13	//! allowed; more than one is a usage error.  The "is stdin a terminal" decision
14	//! and the stdin reader are injected so the resolution rules can be unit-tested
15	//! without a real TTY.
16	
17	use std::io::Read;
18	use std::path::Path;
19	
20	use crate::CliError;
21	
22	/// The `-` sentinel that means "read from stdin" when supplied as the prompt
23	/// string or as the `--prompt-file` value.
24	const STDIN_SENTINEL: &str = "-";
25	
26	/// Resolve the feature prompt from the available sources.
27	///
28	/// * `prompt` — the positional argument / `--prompt` string (if any).
29	/// * `prompt_file` — the `--prompt-file` value (a path, or `-` for stdin).
30	/// * `stdin_is_terminal` — whether stdin is attached to a terminal; inject
31	///   [`std::io::IsTerminal`] at the call site.
32	/// * `read_stdin` — a closure that reads stdin to a `String`; injected so tests
33	///   can supply a fixed reader.
34	///
35	/// ## Resolution rules
36	///
37	/// * stdin is used when the prompt string is exactly `-`, **or**
38	///   `--prompt-file -` is given, **or** no prompt string and no `--prompt-file`
39	///   is given and stdin is not a terminal (piped input).
40	/// * Supplying more than one explicit source (e.g. a non-`-` positional string
41	///   *and* `--prompt-file`) is a usage error.
42	/// * A missing or unreadable `--prompt-file` is an error naming the path.
43	/// * A single trailing newline is trimmed; a prompt that is empty or
44	///   whitespace-only after trimming is rejected.
45	/// * When nothing is supplied and stdin **is** a terminal, returns `Ok(None)`
46	///   so the caller's interactive no-prompt fallback still fires.
47	pub(crate) fn resolve_prompt<R>(
48	    prompt: Option<String>,
49	    prompt_file: Option<String>,
50	    stdin_is_terminal: bool,
51	    read_stdin: R,
52	) -> Result<Option<String>, CliError>
53	where
54	    R: FnOnce() -> std::io::Result<String>,
55	{
56	    // Classify the prompt string: a literal `-` is a stdin request, not text.
57	    let prompt_is_stdin = prompt.as_deref() == Some(STDIN_SENTINEL);
58	    let prompt_text = if prompt_is_stdin { None } else { prompt };
59	
60	    // Classify `--prompt-file`: `-` is a stdin request, not a path.
61	    let file_is_stdin = prompt_file.as_deref() == Some(STDIN_SENTINEL);
62	    let file_path = if file_is_stdin { None } else { prompt_file };
63	
64	    let wants_stdin = prompt_is_stdin || file_is_stdin;
65	
66	    // Count explicit sources; more than one is ambiguous.
67	    let explicit_sources = usize::from(prompt_text.is_some())
68	        + usize::from(file_path.is_some())
69	        + usize::from(wants_stdin);
70	    if explicit_sources > 1 {
71	        return Err(crate::message(
72	            "provide the prompt as a positional argument, --prompt-file, or stdin \
73	             — not more than one",
74	        ));
75	    }
76	
77	    let raw = if let Some(text) = prompt_text {
78	        text
79	    } else if let Some(path) = file_path {
80	        read_prompt_file(Path::new(&path))?
81	    } else if wants_stdin {
82	        read_stdin().map_err(|source| {
83	            crate::message(format!("failed to read the prompt from stdin: {source}"))
84	        })?
85	    } else if stdin_is_terminal {
86	        // Nothing supplied and stdin is interactive: preserve the caller's
87	        // no-prompt fallback (e.g. incomplete-run detection).
88	        return Ok(None);
89	    } else {
90	        // Nothing supplied but stdin is piped: read it.
91	        read_stdin().map_err(|source| {
92	            crate::message(format!("failed to read the prompt from stdin: {source}"))
93	        })?
94	    };
95	
96	    Ok(Some(normalise(raw)?))
97	}
98	
99	/// Read a prompt file, mapping any IO failure to an error naming the path.
100	fn read_prompt_file(path: &Path) -> Result<String, CliError> {
101	    std::fs::read_to_string(path).map_err(|source| CliError::Io {
102	        path: path.to_path_buf(),
103	        source,
104	    })
